changeSet.sql:
DELETE FROM pkg_packaging_submission;
ALTER TABLE pkg_packaging_submission DROP CONSTRAINT ck_pkg_packaging_submission_status, ALTER COLUMN status TYPE varchar(40), ADD CONSTRAINT ck_pkg_packaging_submission_status CHECK (status IN ('InProgress', 'SubmittedToRegulator', 'AcceptedByRegulator', 'RejectedByRegulator')), -- Set when a compliance scheme submits for its members; null for a direct producer. ADD COLUMN compliance_scheme_id uuid, -- period_packaging_submission_period.name, for example 'July to December 2025'. Not a foreign key: -- writes don't cross modules. ADD COLUMN submission_period varchar(100) NOT NULL;
DROP INDEX ix_pkg_packaging_submission_organisation_year;
-- One submission per submitter and period. NULLS NOT DISTINCT, so two direct producer rows (no -- compliance scheme) for the same organisation and period also clash. CREATE UNIQUE INDEX uq_pkg_packaging_submission_submitter_period ON pkg_packaging_submission (organisation_id, compliance_scheme_id, submission_period) NULLS NOT DISTINCT;

CREATE TABLE pkg_submission_file ( id uuid NOT NULL CONSTRAINT pk_pkg_submission_file PRIMARY KEY, packaging_submission_id uuid NOT NULL CONSTRAINT fk_pkg_submission_file_submission REFERENCES pkg_packaging_submission (id), submission_cycle_id uuid NOT NULL CONSTRAINT fk_pkg_submission_file_cycle REFERENCES pkg_submission_cycle (id), status varchar(20) NOT NULL CONSTRAINT ck_pkg_submission_file_status CHECK (status IN ('Uploading', 'Rejected', 'Validating', 'Invalid', 'Valid')), -- The secret in the callback URL given to the CDP uploader for this upload. callback_token varchar(64) NOT NULL, -- From the uploader's callback: known once the file has been scanned. file_name varchar(260), s3_bucket varchar(100), s3_key varchar(1024), rejection_reason varchar(1000), -- From validating the file, which happens after it is stored, as a step of its own. error_count integer, warning_count integer, started_by_user_id uuid NOT NULL, started_at timestamptz NOT NULL, scanned_at timestamptz, validated_at timestamptz );
CREATE INDEX ix_pkg_submission_file_submission ON pkg_submission_file (packaging_submission_id);
-- A file belongs to a cycle, and a cycle names the file it submitted, so the two tables reference each -- other. This one is checked at commit, so a cycle and its file can be inserted in either order. ALTER TABLE pkg_submission_cycle ADD CONSTRAINT fk_pkg_submission_cycle_submitted_file FOREIGN KEY (submitted_file_id) REFERENCES pkg_submission_file (id) DEFERRABLE INITIALLY DEFERRED;
